<?php $escape=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$money=static fn(array $row):string=>number_format((float)$row['montant'],2,',',' ').' '.$row['devise'];$groups=[];foreach($remittances as $row)$groups[(int)$row['id_tournee']][]=$row; ?>
<section class="container courier-tours"><a href="/admin/livreurs">← Livreurs</a><h1>Argent des livraisons</h1><p>Confirmez uniquement l’argent physiquement reçu du livreur. Chaque devise est comptée séparément.</p>
<?php if(is_string($flash)): ?><p role="status"><?= $escape($flash) ?></p><?php endif; ?>
<?php if(!$groups): ?><p>Aucune remise en attente après retour.</p><?php endif; ?>
<?php foreach($groups as $id=>$currencies): $label=implode(' + ',array_map($money,$currencies)); ?>
<article class="courier-tour courier-remittance"><p class="courier-eyebrow">Argent à récupérer</p><h2><?= $escape($currencies[0]['nom_livreur_snapshot']) ?></h2><?php $count=array_sum(array_column($currencies,'livraisons')); ?><p><?= $count ?> <?= $count===1?'livraison':'livraisons' ?></p><p>Montant attendu <strong class="courier-remittance__amount"><?= $escape($label) ?></strong></p>
<form method="post" action="/admin/remises-cash/confirmer" data-tour-form><input type="hidden" name="_token" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="tournee" value="<?= $id ?>"><input type="hidden" name="mode" value="exact"><button class="btn btn-primary">Confirmer <?= $escape($label) ?> reçus</button></form>
<details class="courier-exception"><summary>Signaler un écart</summary><p>Montant attendu : <?= $escape($label) ?>. Le signalement ne valide aucune remise ni aucun paiement.</p>
<form method="post" action="/admin/remises-cash/confirmer" data-tour-form><input type="hidden" name="_token" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="tournee" value="<?= $id ?>"><input type="hidden" name="mode" value="ecart">
<?php foreach($currencies as $row): ?><label>Montant réellement reçu (<?= $escape($row['devise']) ?>)<input name="montants[<?= $escape($row['devise']) ?>]" required inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" placeholder="0.00"></label><?php endforeach; ?>
<label>Motif<textarea name="motif" required maxlength="500"></textarea></label><button class="btn btn-outline">Enregistrer l’écart</button></form></details></article><?php endforeach; ?></section>
